"""Parser matching the compiled binary reader."""

MAGIC = 0xBEB6F6F3
MAX_FILE_SIZE = 65536


def parse(data: bytes):
    """Return the parsed record as a dict, or None if the data is invalid."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    end = len(data)

    if end > MAX_FILE_SIZE or end < 9:
        return None
    if int.from_bytes(data[0:4], "little") != MAGIC:
        return None
    if data[4] != 0xC9:
        return None

    offset = 5

    def read_uint(width):
        nonlocal offset
        if offset > end or width > end - offset:
            raise ValueError
        value = int.from_bytes(data[offset:offset + width], "little")
        offset += width
        return value

    try:
        record_count = read_uint(4)
        if record_count > 8:
            return None
        name = read_uint(4)
        qty = read_uint(4)
        version = read_uint(1)

        records = []
        for _ in range(record_count):
            stock = read_uint(1)
            code = read_uint(2)
            score = read_uint(4)
            record_version = read_uint(2)
            balance = read_uint(2)
            records.append({
                "balance": balance,
                "code": code,
                "score": score,
                "stock": stock,
                "version": record_version,
            })
    except ValueError:
        return None

    if offset != end:
        return None

    return {
        "header": {
            "name": name,
            "qty": qty,
            "version": version,
        },
        "records": records,
    }
