"""Parser matching the supplied binary reader."""

from __future__ import annotations


def _read_u(data: bytes, offset: int, width: int) -> tuple[int, int] | None:
    if offset < 0 or offset > len(data) or width > len(data) - offset:
        return None
    return int.from_bytes(data[offset : offset + width], "little"), offset + width


def parse(data: bytes) -> dict | None:
    """Parse *data*, returning the reader's JSON object as a dict.

    Return ``None`` for any input the reference reader would report as
    ``INVALID``.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None

    data = bytes(data)
    end = len(data)

    # The reference reader refuses files larger than 64 KiB.
    if end > 65536:
        return None
    if end < 9:
        return None

    if data[0:4] != b"\xc5\x51\x00\x5d":
        return None
    if data[4] != 0xDA:
        return None

    offset = 5

    result = _read_u(data, offset, 4)
    if result is None:
        return None
    record_count, offset = result
    if record_count > 8:
        return None

    result = _read_u(data, offset, 2)
    if result is None:
        return None
    account_id, offset = result

    records = []
    for _ in range(record_count):
        result = _read_u(data, offset, 2)
        if result is None:
            return None
        version, offset = result

        result = _read_u(data, offset, 1)
        if result is None:
            return None
        rating, offset = result

        result = _read_u(data, offset, 2)
        if result is None:
            return None
        timestamp, offset = result

        records.append(
            {
                "rating": rating,
                "timestamp": timestamp,
                "version": version,
            }
        )

    if offset != end:
        return None

    return {"header": {"account_id": account_id}, "records": records}
