"""Parser matching the behaviour of the compiled ``reader`` program."""

_MAGIC = 0x44DF83DC
_MAX_FILE_SIZE = 65536
_MAX_RECORDS = 8


def _read_number(data: bytes, offset: int, width: int):
    """Read a little-endian unsigned integer, or return (False, ...)."""
    if offset > len(data) or width > len(data) - offset:
        return False, offset, 0
    value = int.from_bytes(data[offset:offset + width], "little")
    return True, offset + width, value


def parse(data: bytes) -> dict | None:
    payload_end = len(data)
    offset = 5

    # The reader rejects files larger than 64 KiB.
    if payload_end > _MAX_FILE_SIZE:
        return None
    if payload_end < 5 + 4:
        return None

    actual_magic = int.from_bytes(data[0:4], "little")
    if actual_magic != _MAGIC:
        return None
    if data[4] != 0x76:
        return None

    ok, offset, record_count = _read_number(data, offset, 4)
    if not ok or record_count > _MAX_RECORDS:
        return None

    header_values = [0, 0]
    ok, offset, header_values[0] = _read_number(data, offset, 1)
    if not ok:
